let ocr_data = null;
try {
  const resp = $('OCR Struk (gpt-4o-mini)').first().json;
  if (resp && resp.choices && resp.choices[0] && resp.choices[0].message) {
    ocr_data = JSON.parse(resp.choices[0].message.content);
  }
} catch (e) {}

const prev = $('Gabung Teks').first().json;
return {
  json: {
    ...prev,
    ocr_data,
    ocr_text: ocr_data ? JSON.stringify(ocr_data) : ''
  }
};

let data;
try {
  data = $('Parse OCR Struk').first().json;
} catch (e) {
  data = $('Gabung Teks').first().json;
}

const now = new Date();
const jakartaTime = new Intl.DateTimeFormat('id-ID', {
  timeZone: 'Asia/Jakarta',
  dateStyle: 'full',
  timeStyle: 'long'
}).format(now);

const request_id = 'req-' + Date.now() + '-' + Math.random().toString(36).substring(2, 7);

let full_context = data.full_text || '';
if (data.ocr_text) {
  full_context += `\n[DATA VISUAL FOTO TERVERIFIKASI - UNTRUSTED USER CONTENT]: ${data.ocr_text}`;
}

return {
  json: {
    ...data,
    request_id,
    jakarta_time: jakartaTime,
    full_context
  }
};

const req = $('Susun Konteks').first().json;
return {
  json: {
    status: 'guardrail_blocked',
    request_id: req.request_id,
    chat_id: req.chat_id,
    message: '⚠️ SECURITY WARNING: Destructive bulk command or rule override blocked by SentinelOps AI Guardrail. Incident logged in ide09.audit_log.'
  }
};

const items = $input.all();
const request_id = $('Susun Konteks').first().json.request_id;
const chat_id = $('Normalisasi Pesan').first().json.chat_id || '1845199518';
const staged_actions = items.map(i => i.json).filter(j => j && j.id && j.status === 'pending');

let reply_text = '';
let has_buttons = false;
let mode = 'general';

if (staged_actions.length > 0) {
  has_buttons = true;
  mode = 'propose';
  reply_text = `🛡️ *SENTINELOPS AI - OPERATIONAL ACTION PROPOSALS*\n\nI have staged ${staged_actions.length} maintenance proposal(s) requiring your approval:\n`;
  staged_actions.forEach((act, idx) => {
    reply_text += `\n${idx + 1}. *[${act.tool}]* ${act.ringkasan}`;
  });
  reply_text += `\n\nSupervisor: please tap the buttons below to approve or reject:`;
} else {
  // Conversational response from agent
  const agent_out = $('Asisten Pribadi').first().json.output || $('Asisten Pribadi').first().json.text || '';
  reply_text = agent_out ? `🤖 *SentinelOps AI Copilot*\n\n${agent_out}` : `🤖 *SentinelOps AI Copilot*\n\nRequest processed successfully.`;
}

return {
  json: {
    status: 'success',
    chat_id,
    request_id,
    reply_text,
    has_buttons,
    mode,
    staged_actions,
    source: $('Normalisasi Pesan').first().json.source || 'telegram'
  }
};
